import java.io.*;
import java.util.StringTokenizer;

/**
 * Slightly different code structure with explicit method calls.
 */
public class Main {
    public static void main(String[] args) throws IOException {
        InputStream inStream = System.in;
        OutputStream outStream = System.out;
        BufferedReader reader = new BufferedReader(new InputStreamReader(inStream));
        PrintWriter writer = new PrintWriter(outStream);
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(tokenizer.nextToken());
        int k = Integer.parseInt(tokenizer.nextToken());
        int l = Integer.parseInt(tokenizer.nextToken());

        int MOD = 998244353;
        long[] invs = IntegerUtils.invs(2 * n + 3, MOD);
        long[][] dp = new long[2 * n + 1][n + 1];
        initializeDP(dp);
        fillDP(dp, n, invs, MOD);

        long totalAnswer = computeAnswer(dp, n, k, l, invs, MOD);
        writer.println(totalAnswer);
        writer.close();
    }

    static void initializeDP(long[][] dp) {
        dp[0][1] = 1;
    }

    static void fillDP(long[][] dp, int n, long[] invs, int mod) {
        for (int i = 1; i < 2 * n; i++) {
            int prevMax = Math.min(2 * n - i, i);
            int maxRunning = Math.min(2 * n - i - 1, i + 1);
            for (int j = 0; j <= prevMax; j++) {
                if (dp[i - 1][j] != 0) {
                    if (j > 0) {
                        dp[i][j - 1] = (dp[i][j - 1] + dp[i - 1][j] * j % mod * invs[2 * n - i]) % mod;
                    }
                    if (j < maxRunning) {
                        dp[i][j + 1] = (dp[i][j + 1] + dp[i - 1][j] * (2 * n - i - j) % mod * invs[2 * n - i]) % mod;
                    }
                }
            }
        }
    }

    static long computeAnswer(long[][] dp, int n, int k, int l, long[] invs, int mod) {
        long ans = 0;
        for (int i = 0; i < 2 * n; i++) {
            for (int j = k; j <= n; j++) {
                ans = (ans + dp[i][j]) % mod;
            }
        }
        ans = ans * l % mod * invs[2 * n + 1] % mod;
        return ans;
    }

    static class IntegerUtils {
        public static long[] invs(int n, long p) {
            long[] res = new long[n];
            res[1] = 1;
            for (int i = 2; i < n; i++) {
                res[i] = (p - (p / i) * res[(int) (p % i)] % p) % p;
            }
            return res;
        }
    }
}
